import{_ as r,l,o as e,c as s,v as t,p as n,x as o,d as h,i as d,S as E}from"./chunks/framework.InCnrqk-.js";const P=JSON.parse('{"title":"铬与 MoSi 膜层","description":"","frontmatter":{"title":"铬与 MoSi 膜层","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/chrome-mosi-films.md","filePath":"litho/chrome-mosi-films.md","lastUpdated":1789023840000}'),m={name:"litho/chrome-mosi-films.md"};function p(c,a,M,S,_,f){const i=l("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="铬与-mosi-膜层" tabindex="-1">铬与 MoSi 膜层 <a class="header-anchor" href="#铬与-mosi-膜层" aria-label="Permalink to &quot;铬与 MoSi 膜层&quot;">​</a></h1><div class="epigraph"><p>二元版靠铬（或等价金属）挡光；衰减相移靠 MoSi 一类半透膜把相位与透过率绑在同一开口上。</p><footer>—— 对照二元铬掩模与衰减相移掩模（attPSM）膜系的教科书与产线通称</footer></div><p><a href="/litho/mask-blank-ltem">上一课</a>把坯钉成 LTEM/石英光学元件。缺口是面上要长什么膜：挡光、相移、还是 EUV 吸收体。本课钉 DUV 主流的铬与 MoSi。膜怎么被刻出侧壁，留给[下一课](/litho/mask-etch-sidewall）。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>二元掩模：开口透、铬挡，相位跳变主要来自石英台阶（若有）和边缘 3D。衰减相移（attPSM）：MoSi 等材料在 193 nm 提供约数百分比透过与约 180° 相移，边衬对比靠相消，而不是靠铬那么「黑」。EUV 不用这套透射 MoSi 故事，而用高 Z 吸收体（Ta 化合物等）盖在 Mo/Si 多层上——本课只对照，不重写 <a href="/litho/low-n-absorber">低 n 吸收体</a>。</p><p>缺口是<strong>膜系选择改成像边</strong>，不是再选基板。把所有 DUV 版当成二元铬，会在 attPSM 层上用错 3D 与修边模型。</p><h3 id="透过率与相位是一对-不是两个旋钮" tabindex="-1">透过率与相位是一对，不是两个旋钮 <a class="header-anchor" href="#透过率与相位是一对-不是两个旋钮" aria-label="Permalink to &quot;透过率与相位是一对，不是两个旋钮&quot;">​</a></h3><p>attPSM 的设计透过率（历史上常见 ~6% 量级的叙述，具体以技术文件为准）与相移绑定在膜厚与色散上。改厚去贴相位，透过率跟着走。OPC 模型必须用对膜，否则助条与主图形的干涉条件全错。</p><p><span class="marginnote">MoSi 刻蚀与铬刻蚀的负载、侧壁、微沟槽不同，MPC 表不能共用。下一课侧壁会把这件事变成 3D 边缘。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>膜堆：铬常含防反光氧化层；MoSi 常有氧化帽。厚度按波长与相位目标镀。缺陷：针孔在二元上是亮缺陷，在相移膜上还带相位。来料检验与后段图形检验的灵敏度对不同膜系不同。</p><p>与成像：二元边更「硬」，MEEF 与 3D 仍在；attPSM 改善某些节距的 NILS，却对膜厚误差和侧壁更敏感。层选膜是 DTCO/RET 决策，不是掩模厂临时改镀。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>铬的光学厚度以吸收为主；边缘的电磁是导体/介质过渡，<a href="/litho/mask-3d-effect">掩模 3D</a> 仍存在。MoSi 半透，开口与膜区的相位差在焦点附近给出更陡的强度边，同时也给出旁瓣——助条与偏置必须按相移成像来，不能按二元经验。EUV 吸收体是反射几何里的阴影与相移，物理另一套，只是「膜决定边」这一句同构。</p>',14)),(e(),n(E,null,{default:o(()=>[d(i,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TD%0A%20%20QZ%5B%22%E7%9F%B3%E8%8B%B1%20%2F%20LTEM%22%5D%20--%3E%20BIN%5B%22%E9%93%AC%E4%BA%8C%E5%85%83%22%5D%0A%20%20QZ%20--%3E%20ATT%5B%22MoSi%20attPSM%22%5D%0A%20%20QZ%20--%3E%20EUV%5B%22EUV%20%E5%A4%9A%E5%B1%82%20%2B%20%E5%90%B8%E6%94%B6%E4%BD%93%22%5D%0A%20%20BIN%20--%3E%20IMG%5B%22%E9%80%8F%E5%B0%84%E6%88%90%E5%83%8F%E8%BE%B9%22%5D%0A%20%20ATT%20--%3E%20IMG%0A%20%20EUV%20--%3E%20REFL%5B%22%E5%8F%8D%E5%B0%84%E6%88%90%E5%83%8F%E8%BE%B9%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[h(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不把 6% 写成所有 attPSM 的定律。不讨论某供应商商标膜名。EUV 膜堆细节不在本课展开。</p><p>后课默认：DUV 版的吸收/相移膜已选定；下一课刻蚀如何把膜边做成有倾角的三维物体。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>二元铬挡光；MoSi attPSM 把弱透过与相移绑在膜厚上。</li><li>OPC 必须用对膜系；MPC 随刻蚀化学变。</li><li>EUV 吸收体是反射几何的另一套膜，同构的是「膜即边缘」。</li><li>出处：Levinson / Mack 对二元与衰减相移掩模的论述；产线 attPSM 通称。</li></ul>',5))])}const u=r(m,[["render",p]]);export{P as __pageData,u as default};
